    case 75: return equalityExpressionSempred(antlrcpp::downCast<EqualityExpressionContext *>(context), predicateIndex);
    case 76: return andExpressionSempred(antlrcpp::downCast<AndExpressionContext *>(context), predicateIndex);
    case 77: return exclusiveOrExpressionSempred(antlrcpp::downCast<ExclusiveOrExpressionContext *>(context), predicateIndex);
    case 78: return inclusiveOrExpressionSempred(antlrcpp::downCast<InclusiveOrExpressionContext *>(context), predicateIndex);
